const body = $input.first().json.body || {};
const contactId = parseInt(body.contact_id, 10);
if (!Number.isInteger(contactId)) throw new Error('"contact_id" is required.');
return [{ json: { contactId, source: (body.source || 'unknown').toString() } }];

// alwaysOutputData placeholder from a zero-row match (no compiled
// contact-created automations exist yet) — nothing to fire, respond
// success either way since the CALLER (a contact-creation flow) must
// never fail just because no automation currently cares.
const contactId = $('Parse Payload').first().json.contactId;
const rows = $input.all().map((i) => i.json).filter((r) => r.id != null && r.n8n_workflow_id);
return rows.map((r) => ({ json: { automationId: r.id, contactId, url: `http://localhost:5678/webhook/automation-${r.id}-trigger` } }));
